function scanAudit(D,vs){
 let seed=271828182,random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed>>>31},samples=1024,gates=0,depth=0;
 for(let w=0;w<samples;w++){let A=new Map(vs.map(v=>[v,random()])),h=D.map(d=>Number(d.c.every(l=>A.get(Math.abs(l))===Number(l<0)))),z=h.map(v=>1-v),count=0,levels=0;
 for(let step=1;step<z.length;step*=2){let old=z;z=old.map((v,i)=>i>=step?(count++,v&old[i-step]):v);levels++}
 let t=h.map((v,i)=>v*(i?z[i-1]:1));if(t.reduce((s,v)=>s+v,0)!==1||t.some((v,i)=>v&&D[i].p[0]!=="base"))throw Error("prefix");
 gates=count;depth=levels;
 }return {samples,gates,depth,terms:D.filter(d=>d.p[0]==="base").length};
